//! Shared vectors: generated by replaying upstream `spark-frost` (or, for
//! `frost-commit`, by `spark-crypto` itself), verified by replaying them
//! through `spark-crypto`.
//!
//! `SPARK_WRITE_VECTORS=1 cargo test -p qntx-spark-interop --test vectors`
//! regenerates the files under the repository-root `vectors/` directory;
//! otherwise this test asserts `spark-crypto` reproduces them byte-for-byte
//! and that upstream accepts our outputs.

#![allow(
    unused_crate_dependencies,
    clippy::tests_outside_test_module,
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::missing_panics_doc,
    reason = "test code"
)]

mod common;

use std::path::{Path, PathBuf};

use common::*;
use frost::keys::Tweak;
use frost::{Identifier, SigningKey, VerifyingKey};
use frost_secp256k1_tr as frost;
use serde_json::{Value, json};

fn vectors_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../vectors")
        .canonicalize()
        .unwrap()
}

fn header(source: &str) -> Value {
    json!({
        "source": source,
        "upstream": format!("buildonspark/spark@{UPSTREAM_REV}"),
        "note": "Test vectors only. Never use these keys for funds.",
    })
}

fn write_or_check(name: &str, document: &Value) {
    let path = vectors_dir().join(name);
    if std::env::var_os("SPARK_WRITE_VECTORS").is_some() {
        std::fs::write(
            &path,
            serde_json::to_string_pretty(&document).unwrap() + "\n",
        )
        .unwrap();
        return;
    }
    let stored: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    assert_eq!(
        &stored, document,
        "{name} differs; regenerate with SPARK_WRITE_VECTORS=1"
    );
}

fn hex_str(bytes: &[u8]) -> String {
    hex::encode(bytes)
}

fn unhex(value: &Value) -> Vec<u8> {
    hex::decode(value.as_str().unwrap()).unwrap()
}

// -- frost-commit -----------------------------------------------------------

fn commit_cases() -> Vec<Value> {
    let mut cases = Vec::new();
    for i in 0..4u8 {
        let mut hedge = [0u8; 32];
        hedge[31] = i + 1;
        let random = [i.wrapping_add(0xA0); 32];
        let c = spark_crypto::frost::commit(&hedge, &random).unwrap();
        cases.push(json!({
            "hedge": hex_str(&hedge),
            "random": hex_str(&random),
            "nonces": hex_str(c.nonces()),
            "commitments": hex_str(c.commitments()),
        }));
    }
    cases
}

#[test]
fn vectors_frost_commit() {
    let document = json!({
        "header": header("self"),
        "cases": commit_cases(),
    });
    write_or_check("frost-commit.json", &document);
}

// -- frost-sign + frost-aggregate -------------------------------------------

fn frost_case(seed: u8, signers: &[u16], adaptor: bool) -> Value {
    let mut rand = rng(seed);
    let setup = setup(&mut rand, 3, 2, &[1, 2, 3]);
    let message = format!("spark-frost vector {seed}").into_bytes();
    let adaptor_key = adaptor.then(|| {
        VerifyingKey::from(&SigningKey::new(&mut rand))
            .serialize()
            .unwrap()
    });
    let (round, user_round1) = build_round(&setup, signers, &message, adaptor_key, seed);
    let outcome = run_both(&round, &setup, &user_round1);

    // Non-adaptor signatures must verify as plain BIP-340 against the
    // taproot-tweaked (empty merkle root) combined key.
    if round.adaptor.is_none() {
        let mut map = std::collections::BTreeMap::new();
        for (id, op) in &setup.operators {
            map.insert(
                *id,
                frost::keys::VerifyingShare::deserialize(&op.verifying_share).unwrap(),
            );
        }
        let user_id = Identifier::derive(b"user").unwrap();
        map.insert(
            user_id,
            frost::keys::VerifyingShare::new(setup.user_vk.to_element()),
        );
        let package =
            frost::keys::PublicKeyPackage::new(map, setup.combined_vk, None).tweak(Some(&[]));
        let sig = frost::Signature::deserialize(&outcome.our_signature).unwrap();
        package
            .verifying_key()
            .verify(&round.message, &sig)
            .expect("aggregated signature must verify");
    }

    let operators: Vec<Value> = round
        .signer_ids
        .iter()
        .map(|id| {
            let op = &setup.operators[id];
            json!({
                "identifier": hex_str(&id_bytes(id)),
                "commitment": hex_str(&commitment_bytes(&op.commitment)),
                "signature_share": hex_str(&outcome.operator_shares[&id_hex(id)]),
                "public_key": hex_str(&op.verifying_share),
            })
        })
        .collect();

    json!({
        "message": hex_str(&round.message),
        "secret_key": hex_str(&setup.user_key.serialize()),
        "verifying_key": hex_str(&round.verifying_key),
        "nonce": hex_str(&user_round1.nonce_bytes),
        "user_commitment": hex_str(&user_round1.commitment_bytes),
        "user_public_key": hex_str(&setup.user_vk.serialize().unwrap()),
        "operators": operators,
        "adaptor_public_key": round.adaptor.as_ref().map(|a| hex_str(a)),
        "signature_share": hex_str(&outcome.upstream_user_share),
        "signature": hex_str(&outcome.upstream_signature),
    })
}

fn frost_cases() -> Vec<Value> {
    // operator sets {1,2,3}, {1,2}, {2,3} with and without adaptor.
    let mut cases = Vec::new();
    let mut seed = 1u8;
    for signers in [&[1u16, 2, 3][..], &[1, 2], &[2, 3], &[1, 3]] {
        for adaptor in [false, true] {
            cases.push(frost_case(seed, signers, adaptor));
            seed += 1;
        }
    }
    cases
}

#[test]
fn vectors_frost_sign() {
    let document = json!({
        "header": header("upstream"),
        "cases": frost_cases(),
    });
    write_or_check("frost-sign.json", &document);
}

// -- ecies -------------------------------------------------------------------

fn ecies_cases() -> Vec<Value> {
    let mut cases = Vec::new();
    let mut rand = rng(0xEC);
    for i in 0..4u8 {
        let sk = SigningKey::new(&mut rand);
        let sk_bytes: [u8; 32] = sk.serialize().try_into().unwrap();
        let vk = VerifyingKey::from(&sk).serialize().unwrap();
        let plaintext = format!("ecies message {i}").into_bytes();
        let random = [i.wrapping_add(0x50); 32];
        let ciphertext = spark_crypto::ecies::encrypt(&vk, &plaintext, &random).unwrap();
        // The upstream crate must be able to decrypt our output.
        assert_eq!(
            spark_frost::bridge::decrypt_ecies(ciphertext.clone(), sk_bytes.to_vec()).unwrap(),
            plaintext
        );
        cases.push(json!({
            "secret_key": hex_str(&sk_bytes),
            "public_key": hex_str(&vk),
            "plaintext": hex_str(&plaintext),
            "random": hex_str(&random),
            "ciphertext": hex_str(&ciphertext),
        }));
    }
    cases
}

#[test]
fn vectors_ecies() {
    // Live cross-check in the other direction (upstream uses OsRng, so it
    // cannot be frozen into a vector).
    let mut rand = rng(0xED);
    let sk = SigningKey::new(&mut rand);
    let sk_bytes: [u8; 32] = sk.serialize().try_into().unwrap();
    let vk = VerifyingKey::from(&sk).serialize().unwrap();
    let upstream_ct = spark_frost::bridge::encrypt_ecies(b"upstream plaintext", &vk).unwrap();
    assert_eq!(
        spark_crypto::ecies::decrypt(&sk_bytes, &upstream_ct).unwrap(),
        b"upstream plaintext"
    );

    let document = json!({
        "header": header("upstream"),
        "cases": ecies_cases(),
    });
    write_or_check("ecies.json", &document);
}

// -- vss ----------------------------------------------------------------------

fn vss_cases() -> Vec<Value> {
    let mut cases = Vec::new();
    for i in 0..4u8 {
        let mut secret = [0u8; 32];
        secret[31] = 41 + i;
        let (threshold, count) = [(2usize, 3usize), (3, 5), (2, 2), (5, 7)][usize::from(i)];
        let random = [i.wrapping_add(0x77); 32];
        let split = spark_crypto::vss::split_secret_with_proofs(&secret, threshold, count, &random)
            .unwrap();

        // Upstream validation: every share verifies, any threshold subset
        // recovers the secret.
        let proofs: Vec<Vec<u8>> = split.proofs().iter().map(Vec::from).collect();
        let shares: Vec<spark_frost::vss::SecretShare> = split
            .shares()
            .iter()
            .enumerate()
            .map(|(i, share)| spark_frost::vss::SecretShare {
                threshold,
                index: u32::try_from(i + 1).unwrap(),
                share: share.to_vec(),
            })
            .collect();
        for share in &shares {
            spark_frost::vss::validate_share(&share.share, share.index, threshold, &proofs)
                .unwrap();
        }
        assert_eq!(
            spark_frost::vss::recover_secret(&shares[..threshold]).unwrap(),
            secret
        );

        cases.push(json!({
            "secret": hex_str(&secret),
            "threshold": threshold,
            "share_count": count,
            "random": hex_str(&random),
            "proofs": split.proofs().iter().map(|p| hex_str(p)).collect::<Vec<_>>(),
            "shares": split.shares().iter().map(|s| hex_str(s)).collect::<Vec<_>>(),
        }));
    }
    cases
}

#[test]
fn vectors_vss() {
    let document = json!({
        "header": header("upstream"),
        "cases": vss_cases(),
    });
    write_or_check("vss.json", &document);
}

// -- verification against stored vectors -------------------------------------

/// Replay the stored frost-sign vectors through `spark-crypto` as a
/// regression check on top of the byte-equal `write_or_check` compare.
#[test]
fn vectors_frost_sign_replay() {
    if std::env::var_os("SPARK_WRITE_VECTORS").is_some() {
        return;
    }
    let path = vectors_dir().join("frost-sign.json");
    let document: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    for case in document["cases"].as_array().unwrap() {
        let secret_key: [u8; 32] = unhex(&case["secret_key"]).try_into().unwrap();
        let verifying_key: [u8; 33] = unhex(&case["verifying_key"]).try_into().unwrap();
        let nonce: [u8; 64] = unhex(&case["nonce"]).try_into().unwrap();
        let user_commitment: [u8; 66] = unhex(&case["user_commitment"]).try_into().unwrap();
        let adaptor = case["adaptor_public_key"]
            .as_str()
            .map(|s| hex::decode(s).unwrap().try_into().unwrap());
        let operators: Vec<spark_crypto::frost::OperatorCommitment> = case["operators"]
            .as_array()
            .unwrap()
            .iter()
            .map(|op| spark_crypto::frost::OperatorCommitment {
                identifier: unhex(&op["identifier"]).try_into().unwrap(),
                commitment: unhex(&op["commitment"]).try_into().unwrap(),
            })
            .collect();
        let message = unhex(&case["message"]);

        let share = spark_crypto::frost::sign(&spark_crypto::frost::SignJob {
            message: &message,
            secret_key: &secret_key,
            verifying_key: &verifying_key,
            nonce: &nonce,
            user_commitment: &user_commitment,
            operators: &operators,
            adaptor_public_key: adaptor.as_ref(),
        })
        .unwrap();
        assert_eq!(share.as_slice(), unhex(&case["signature_share"]).as_slice());

        let operator_shares: Vec<spark_crypto::frost::OperatorShare> = case["operators"]
            .as_array()
            .unwrap()
            .iter()
            .map(|op| spark_crypto::frost::OperatorShare {
                identifier: unhex(&op["identifier"]).try_into().unwrap(),
                commitment: unhex(&op["commitment"]).try_into().unwrap(),
                signature_share: unhex(&op["signature_share"]).try_into().unwrap(),
                public_key: unhex(&op["public_key"]).try_into().unwrap(),
            })
            .collect();
        let user_public_key: [u8; 33] = unhex(&case["user_public_key"]).try_into().unwrap();
        let signature = spark_crypto::frost::aggregate(&spark_crypto::frost::AggregateJob {
            message: &message,
            verifying_key: &verifying_key,
            user_commitment: &user_commitment,
            user_public_key: &user_public_key,
            user_signature_share: &share,
            operators: &operator_shares,
            adaptor_public_key: adaptor.as_ref(),
        })
        .unwrap();
        assert_eq!(signature.as_slice(), unhex(&case["signature"]).as_slice());
    }
}
